  const [s] = input;
  if (typeof actual !== 'string' || actual.length !== s.length) return false;
  for (let i = 0; i < s.length; i++) {
    if (s[i] !== '?' && actual[i] !== s[i]) return false;
    if (actual[i] < 'a' || actual[i] > 'z') return false;
    if (i > 0 && actual[i] === actual[i - 1]) return false;
  }
