function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's needs 1 to 100 characters.';
  if (!/^[a-z?]+$/.test(s)) return 's may contain only lowercase letters and ?.';
  for (let i = 1; i < s.length; i++) {
    if (s[i] !== '?' && s[i] === s[i - 1]) return 'No two adjacent characters of s may be the same letter.';
  }
  return null;
}

