function modifyString(s) {
  // Depth-first search over every letter for every '?', trying 'z' first and backing up on a clash.
  const out = s.split('');
  const fill = i => {
    if (i === out.length) return true;
    if (s[i] !== '?') return (i === 0 || out[i - 1] !== out[i]) && fill(i + 1);
    for (let code = 122; code >= 97; code--) {
      const letter = String.fromCharCode(code);
      if (i > 0 && out[i - 1] === letter) continue;
      out[i] = letter;
      if (fill(i + 1)) return true;
    }
    out[i] = '?';
    return false;
  };
  fill(0);
  return out.join('');
}

