function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const letters = size === 'large' ? 'abcdefghijklmnopqrstuvwxyz' : 'abc';
  const marks = rand();
  let s = '';
  for (let i = 0; i < n; i++) {
    if (rand() < marks) {
      s += '?';
      continue;
    }
    let letter;
    do letter = letters[Math.floor(rand() * letters.length)]; while (letter === s[i - 1]);
    s += letter;
  }
  return [s];
}
